// CGeometry.h
#pragma once
#include <iosfwd>
#include <string>

class CGeometry {
private:
    double m_opacity;
protected:
    std::string m_message;
public:
    CGeometry();
    explicit CGeometry(double opacity);
    virtual void whoAmI(std::ostream& out) const;
    virtual ~CGeometry() {};  // versión anterior a C++11
};

// CGeometry.cpp
#include "CGeometry.h"
#include <ostream>

CGeometry::CGeometry() : m_opacity(0.0), m_message("I am a geometry:") {}

CGeometry::CGeometry(double opacity) : m_opacity(opacity), m_message("I am a geometry:") {}

void CGeometry::whoAmI(std::ostream& out) const {
    out << m_message << std::endl;
}

class CPoint {
private:
    double m_x;
    double m_y;
public:
    CPoint() : m_x(0.0), m_y(0.0) {}
    CPoint(double x, double y) : m_x(x), m_y(y) {}
    friend std::ostream& operator<<(std::ostream& out, const CPoint& point);
};

std::ostream& operator<<(std::ostream& out, const CPoint& point) {
    out << "(" << point.m_x << ", " << point.m_y << ")";
    return out;
}

class CSegment : public CGeometry {
private:
    CPoint m_p1;
    CPoint m_p2;
    double m_length;
    double m_slope;
public:
    CSegment() : CGeometry(), m_length(0.0), m_slope(0.0) {}
    explicit CSegment(double opacity) : CGeometry(opacity), m_length(0.0), m_slope(0.0) {}
    virtual void whoAmI(std::ostream& out) const {
        out << "I am a segment" << std::endl;
    }
};

class CCircle : public CGeometry {
private:
    CPoint m_center;
    double m_diameter;
public:
    CCircle() : CGeometry(), m_diameter(0.0) {}
    virtual void whoAmI(std::ostream& out) const {
        out << "I am a circle" << std::endl;
    }
};

void whoAmI(std::ostream& out) const override {
    out << "I am a segment" << '\n';
}

CSegment& CSegment::operator=(const CSegment& other) {
    if (this != &other) {
        CGeometry::operator=(other);
        m_p1 = other.m_p1;
        m_p2 = other.m_p2;
        m_length = other.m_length;
        m_slope = other.m_slope;
    }
    return *this;
}

CSegment segment;
CCircle circle;
std::vector<CGeometry*> geometries;
geometries.push_back(&segment);
geometries.push_back(&circle);
for (std::vector<CGeometry*>::iterator it = geometries.begin(); it != geometries.end(); ++it) {
    (*it)->whoAmI(std::cout);
}

std::vector<CGeometry*> geometries { &segment, &circle };
for (CGeometry* geometry : geometries) {
    geometry->whoAmI(std::cout);
}

CSegment segment(0.5);
CCircle circle;

std::list<CGeometry> shapes;      // contenedor de objetos base, por valor
shapes.push_back(segment);        // copia solo la parte CGeometry
shapes.push_back(circle);
for (std::list<CGeometry>::iterator it = shapes.begin(); it != shapes.end(); ++it) {
    it->whoAmI(std::cout);
}

CGeometry g = segment;            // también se recorta
g.whoAmI(std::cout);

CGeometry& r = segment;           // una referencia NO recorta
r.whoAmI(std::cout);

std::vector<CGeometry*> geometries;
geometries.push_back(new CSegment());
geometries.push_back(new CCircle());
for (std::vector<CGeometry*>::iterator it = geometries.begin(); it != geometries.end(); ++it) {
    (*it)->whoAmI(std::cout);
}
for (std::vector<CGeometry*>::iterator it = geometries.begin(); it != geometries.end(); ++it) {
    delete *it;
}

std::vector<std::unique_ptr<CGeometry>> geometries;
geometries.push_back(std::make_unique<CSegment>());
geometries.push_back(std::make_unique<CCircle>());
for (const auto& geometry : geometries) {
    geometry->whoAmI(std::cout);
}

class CGeometry {
public:
    virtual ~CGeometry() {};  // versión anterior a C++11
    virtual void print(std::ostream& out) const = 0;
};
// Alternativa desde C++11: virtual ~CGeometry() = default;

std::ostream& operator<<(std::ostream& out, const CGeometry& geometry) {
    geometry.print(out);
    return out;
}

class CSegment : public CGeometry {
public:
    virtual void print(std::ostream& out) const {
        out << "Segment: " << m_p1 << ' ' << m_p2;
    }
};

class CCircle : public CGeometry {
public:
    virtual void print(std::ostream& out) const {
        out << "Circle: " << m_center << ' ' << m_diameter;
    }
};

#include "CGeometry.h"
#include "CSegment.h"
#include "CCircle.h"
#include <iostream>
#include <vector>

// Versión anterior a C++11
int main() {
    std::vector<CGeometry*> geometries;
    geometries.push_back(new CSegment());
    geometries.push_back(new CCircle());
    for (std::vector<CGeometry*>::iterator it = geometries.begin(); it != geometries.end(); ++it) {
        std::cout << **it << std::endl;
    }
    for (std::vector<CGeometry*>::iterator it = geometries.begin(); it != geometries.end(); ++it) {
        delete *it;
    }
    return 0;
}

#include <memory>
#include <vector>

std::vector<std::unique_ptr<CGeometry>> geometries;
geometries.push_back(std::unique_ptr<CGeometry>(new CSegment())); // C++11
geometries.push_back(std::unique_ptr<CGeometry>(new CCircle()));
for (const auto& geometry : geometries) {
    std::cout << *geometry << '\n';
}

